mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("n=5 edges=(0,1),(0,2),(1,3),(2,4)","0,1,1,2,2"),
        ("n=4 edges=(0,1)","0,1,-1,-1"),
        ("n=4 edges=(0,1),(1,2),(2,3)","0,1,2,3"),
        ("n=4 edges=(0,1),(0,2),(0,3)","0,1,1,1"),
        ("n=5 edges=(1,2),(3,4)","0,-1,-1,-1,-1"),
        ("  \nn=5 edges=(0,1),(0,2),(1,3),(2,4)\n  ","0,1,1,2,2"),
        ("\nn=5 edges=(1,2),(3,4)\n","0,-1,-1,-1,-1")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS graph-bfs");
}
